import pandas as pd, numpy as np, statsmodels.formula.api as smf
df=pd.read_csv('data.csv')
# Flexible controls for placebo outcome: D + polynomial/spline in log_hist_days, interactions with region etc
forms = {
'linear': 'dY_placebo ~ D + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)',
'poly2': 'dY_placebo ~ D + (log_hist_days + np.power(log_hist_days,2) + log_pre_gmv + np.power(log_pre_gmv,2) + orders + cat_share + tenure + C(region) + C(tier))',
'poly2_inter': 'dY_placebo ~ D + log_hist_days*C(region) + np.power(log_hist_days,2) + log_pre_gmv + np.power(log_pre_gmv,2) + orders + cat_share + tenure + C(tier)',
'poly3': 'dY_placebo ~ D + (log_hist_days + np.power(log_hist_days,2) + np.power(log_hist_days,3) + log_pre_gmv + np.power(log_pre_gmv,2) + orders + cat_share + tenure + C(region) + C(tier))',
}
for name,f in forms.items():
    try:
        m=smf.ols(f, df).fit(cov_type='HC3')
        print(name, 'D coef', m.params['D'], 'SE', m.bse['D'], 'p', m.pvalues['D'])
    except Exception as e:
        print(name, 'ERROR', e)
